-- =============================================================================
-- 0015_hygiene.sql
--
-- GENERATED by scripts/build-hygiene.mjs. Do not hand-edit.
--
-- Pre-beta cleanup, found by scripts/proofread.mjs reading the live database.
--
-- ORTHOGRAPHY. Rows written by migrations 0005-0009 carry two faults the later
-- generators do not, because the Tamil rules then lived in seven copies that
-- had drifted apart. They now live in scripts/_tamil.mjs.
--
--   the avagraha ऽ, which marks an elided vowel in Devanagari and an
--   apostrophe in IAST, was passing straight through into TAMIL text, where
--   the elision is not marked at all. Devanagari inside Tamil on seven steps.
--
--   the om sign ௐ on three steps, where the published Tamil sources and every
--   later migration write ஓம்.
--
-- No mantra's WORDING changes. Removing a character Tamil does not use is
-- orthography.
--
-- PROSE. Seven philosophy entries rewritten, three of which asserted things
-- about nadis, chakras and nerve centres that nothing here supports.
--
-- Idempotent.
-- =============================================================================

begin;

-- --- orthography -------------------------------------------------------------
update public.pooja_steps set
  mantra_tamil = replace(replace(mantra_tamil, 'ऽ', ''), 'ௐ', 'ஓம்'),
  updated_at = now()
where mantra_tamil is not null
  and (mantra_tamil like '%ऽ%' or mantra_tamil like '%ௐ%');

update public.archana_items set
  invoked_name_ta = replace(replace(invoked_name_ta, 'ऽ', ''), 'ௐ', 'ஓம்'),
  offering_ta = replace(replace(offering_ta, 'ऽ', ''), 'ௐ', 'ஓம்')
where invoked_name_ta like '%ऽ%' or invoked_name_ta like '%ௐ%'
   or offering_ta like '%ऽ%' or offering_ta like '%ௐ%';

update public.namavali_items set
  name_ta = replace(replace(name_ta, 'ऽ', ''), 'ௐ', 'ஓம்')
where name_ta like '%ऽ%' or name_ta like '%ௐ%';

-- --- spacing -----------------------------------------------------------------
-- Runs of spaces left by joining kalpam lines. Newlines are deliberate line
-- breaks inside a mantra and are not touched, so this collapses spaces and tabs
-- only.
update public.pooja_steps set
  mantra_sanskrit = regexp_replace(mantra_sanskrit, '[ \t]{2,}', ' ', 'g'),
  mantra_tamil    = regexp_replace(mantra_tamil,    '[ \t]{2,}', ' ', 'g'),
  mantra_translit = regexp_replace(mantra_translit, '[ \t]{2,}', ' ', 'g'),
  updated_at = now()
where mantra_sanskrit ~ '[ \t]{2,}' or mantra_tamil ~ '[ \t]{2,}' or mantra_translit ~ '[ \t]{2,}';

-- --- prose that went stale, or contradicted another step ---------------------
-- Each is guarded on the old text still being there, so a re-run after someone
-- edits the field by hand is a no-op rather than a silent revert.
-- Durva Pooja (21 Names): said it was the only upachara given twenty-one times, which stopped being true when 0012 made the patra and pushpa poojas twenty-one each
update public.pooja_steps set instruction_en = 'Take arugampul in pairs of blades. Offer one pair at each of the twenty-one names. Durva is the offering Ganesha is said to prefer above every other, which is why it is given in its own right here as well as being one of the twenty-one leaves.', updated_at = now()
where pooja_id = 'ganesha_standard' and step_title_en = 'Durva Pooja (21 Names)' and instruction_en <> 'Take arugampul in pairs of blades. Offer one pair at each of the twenty-one names. Durva is the offering Ganesha is said to prefer above every other, which is why it is given in its own right here as well as being one of the twenty-one leaves.';

-- Ganapathi Ashtottara Shatanamavali: still called the Pushpa Pooja a sixteen-name step; 0012 replaced it with the kalpam's twenty-one flowers
update public.pooja_steps set instruction_en = 'Offer a flower, a pinch of akshatai or a blade of arugampul at each of the hundred and eight names. If time is short the twenty-one-name Pushpa Pooja already done stands in its place, but on Chaturthi itself the full hundred and eight is the practice.', updated_at = now()
where pooja_id = 'ganesha_standard' and step_title_en = 'Ganapathi Ashtottara Shatanamavali' and instruction_en <> 'Offer a flower, a pinch of akshatai or a blade of arugampul at each of the hundred and eight names. If time is short the twenty-one-name Pushpa Pooja already done stands in its place, but on Chaturthi itself the full hundred and eight is the practice.';

-- Dhoopam & Deepam: claimed these were the ONLY upacharas that reach everyone, while the Karpura Neerajanam two steps later says it is the point the rest of the house is called in
update public.pooja_steps set philosophy_en = 'Dhoopam is what the room smells of and deepam is what it looks like. They are the first offerings of the morning that reach anyone standing nearby rather than only the person reciting, which is why the bell is rung through both.', updated_at = now()
where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Dhoopam & Deepam' and philosophy_en <> 'Dhoopam is what the room smells of and deepam is what it looks like. They are the first offerings of the morning that reach anyone standing nearby rather than only the person reciting, which is why the bell is rung through both.';

-- Gandham, Kumkumam & Pushpam: spelled arugampul as "Arukampul", the only place in either pooja that does
update public.pooja_steps set instruction_en = 'Apply Chandanam (Sandalwood) and Kumkumam to the deity. Decorate with arugampul (grass) and flowers.', updated_at = now()
where pooja_id = 'ganesha_standard' and step_title_en = 'Gandham, Kumkumam & Pushpam' and instruction_en <> 'Apply Chandanam (Sandalwood) and Kumkumam to the deity. Decorate with arugampul (grass) and flowers.';

-- --- descriptions ------------------------------------------------------------
update public.poojas set description_en = 'The household Ganesha pooja, kept on Vinayaka Chaturthi in the month of Aavani and on any day a new undertaking needs a clear road. A clay or turmeric Pillaiyar is invoked, worshipped through the sixteen upacharas with twenty-one leaves, twenty-one flowers, twenty-one blades of arugampul and the hundred and eight names, and released at the end of the observance.', description_ta = 'வீட்டில் செய்யப்படும் விநாயகர் பூஜை. ஆவணி மாதத்து விநாயக சதுர்த்தியிலும், புதிய முயற்சி தொடங்கும் எந்த நாளிலும் செய்யலாம். களிமண் அல்லது மஞ்சள் பிள்ளையாரை ஆவாஹனம் செய்து, ஷோடச உபசாரங்களுடன், இருபத்தொரு இலை, இருபத்தொரு புஷ்பம், இருபத்தொரு அருகம்புல், நூற்றெட்டு நாமங்களால் பூஜித்து, விரத முடிவில் உத்வாசனம் செய்யப்படுகிறது.', updated_at = now()
where id = 'ganesha_standard';

-- --- philosophy, rewritten ---------------------------------------------------
-- These are unconditional: they replace named existing text, unlike 0014 which
-- only filled nulls.
update public.pooja_steps set philosophy_en = 'Three sips, three names, and the names are Vishnu''s: Achyuta, Ananta, Govinda. They are the same three whoever the pooja is for, because in Smartha practice every rite opens through Vishnu before it turns to its own deity. What the step does is mark a boundary. You were doing something else a minute ago; from here you are not.', updated_at = now()
where pooja_id = 'ganesha_standard' and step_title_en = 'Achamanam';
update public.pooja_steps set philosophy_en = 'Three sips, three names, and the names are Vishnu''s: Achyuta, Ananta, Govinda. They are the same three whoever the pooja is for, because in Smartha practice every rite opens through Vishnu before it turns to its own deity. What the step does is mark a boundary. You were doing something else a minute ago; from here you are not.', updated_at = now()
where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Achamanam';
update public.pooja_steps set philosophy_en = 'Twelve names of Vishnu touched to twelve places, and again they are the same twelve in any Smartha pooja whichever god it is for. The body is being named part by part before it is asked to do anything. Nothing has been offered yet and no deity has been invited; this is still the performer getting ready.', updated_at = now()
where pooja_id = 'ganesha_standard' and step_title_en = 'Anga Vandanam';
update public.pooja_steps set philosophy_en = 'Twelve names of Vishnu touched to twelve places, and again they are the same twelve in any Smartha pooja whichever god it is for. The body is being named part by part before it is asked to do anything. Nothing has been offered yet and no deity has been invited; this is still the performer getting ready.', updated_at = now()
where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Anga Vandanam';
update public.pooja_steps set philosophy_en = 'The verse never says Ganesha. Shuklambaradharam vishnum shashivarnam chaturbhujam describes a white-robed, four-armed figure the colour of the moon, and different traditions read it as Ganesha or as Vishnu. What it asks for is unambiguous: sarva-vighna-upashantaye, the quieting of every obstacle, said before anything is attempted rather than after something has gone wrong.', updated_at = now()
where pooja_id = 'ganesha_standard' and step_title_en = 'Vighneshwara Dhyanam';
update public.pooja_steps set philosophy_en = 'The verse never says Ganesha. Shuklambaradharam vishnum shashivarnam chaturbhujam describes a white-robed, four-armed figure the colour of the moon, and different traditions read it as Ganesha or as Vishnu. What it asks for is unambiguous: sarva-vighna-upashantaye, the quieting of every obstacle, said before anything is attempted rather than after something has gone wrong.', updated_at = now()
where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Vighneshwara Dhyanam';
update public.pooja_steps set philosophy_en = 'The only step in the whole pooja that is about breathing rather than offering. The seven worlds, the Gayatri, then the line about water and light: it is a long thing to say on a held breath, and the length is the point. In this tradition women do not perform it, which is why the app removes the step for them rather than showing it greyed out.', updated_at = now()
where pooja_id = 'ganesha_standard' and step_title_en = 'Pranayamam';
update public.pooja_steps set philosophy_en = 'The only step in the whole pooja that is about breathing rather than offering. The seven worlds, the Gayatri, then the line about water and light: it is a long thing to say on a held breath, and the length is the point. In this tradition women do not perform it, which is why the app removes the step for them rather than showing it greyed out.', updated_at = now()
where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Pranayamam';
update public.pooja_steps set philosophy_en = 'Seven rivers named over a steel tumbler on a kitchen floor. Note what the verse actually asks: sannidhim kuru, be present in this water. Not a claim that the tumbler holds the Ganga, but a request that it should, which is a different kind of sentence and the one this whole pooja is built out of.', updated_at = now()
where pooja_id = 'ganesha_standard' and step_title_en = 'Kalasha Pooja';
update public.pooja_steps set philosophy_en = 'Seven rivers named over a steel tumbler on a kitchen floor. Note what the verse actually asks: sannidhim kuru, be present in this water. Not a claim that the tumbler holds the Ganga, but a request that it should, which is a different kind of sentence and the one this whole pooja is built out of.', updated_at = now()
where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Kalasha Pooja';
update public.pooja_steps set philosophy_en = 'Twenty-nine names, and almost every one begins with the same sound as the limb it worships: Parvatinandana at the feet, Guhagraja at the groin, Natha at the navel, Phalachandra at the forehead. That is a mnemonic, and it is how the list survived without being written down. Note also that it does not stop politely at the waist. The body is worshipped entire.', updated_at = now()
where pooja_id = 'ganesha_standard' and step_title_en = 'Anga Pooja';
update public.pooja_steps set philosophy_en = 'Yat pujitam maya deva paripurnam tad astu te: whatever I have worshipped, let it stand complete FOR YOU. Not "forgive me" and not "I did my best". Completion is asked for as something the deity grants, not something the performer achieved, which is why the verse can concede mantra, rite and devotion all at once and still end the pooja properly.', updated_at = now()
where pooja_id = 'ganesha_standard' and step_title_en = 'Kshama Prarthana & Conclusion';

do $$
declare bad text;
begin
  select string_agg(pooja_id || ' / ' || step_title_en, ', ') into bad
    from public.pooja_steps
   where philosophy_en is null or meaning_en is null
      or mantra_tamil like '%ऽ%' or mantra_tamil like '%ௐ%';
  if bad is not null then
    raise exception 'still wrong after 0015: %', bad;
  end if;
end $$;

commit;

